export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface Scenario {
  customer: { yearsWithMHPCO: number };
  steps: QuoteStep[];
}

export interface ScenarioResults {
  results: object[];
}

const PROCESSING_FEE = 5;
const ITEM_BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
};
const COMPONENT_TYPES = ["rune", "moonstone"];
const COMPONENT_BASE_PREMIUM = 25;
const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;
const PERCENT = 100;
const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
const CURSE_SURCHARGE_PERCENT = 50;

function alikeComponentsBasePremium(count: number): number {
  return count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * COMPONENT_BASE_PREMIUM;
}

function policyBasePremium(items: Item[]): number {
  const itemsPremium = items
    .filter((item) => !COMPONENT_TYPES.includes(item.type))
    .reduce((sum, item) => sum + ITEM_BASE_PREMIUMS[item.type], 0);
  const componentsPremium = COMPONENT_TYPES.reduce(
    (sum, componentType) =>
      sum + alikeComponentsBasePremium(items.filter((item) => item.type === componentType).length),
    0,
  );
  return itemsPremium + componentsPremium;
}

function itemSurchargePercent(item: Item): number {
  return item.cursed ? CURSE_SURCHARGE_PERCENT : 0;
}

function itemSurchargesInPercent(items: Item[]): number {
  return items
    .filter((item) => itemSurchargePercent(item) > 0)
    .reduce((sum, item) => sum + ITEM_BASE_PREMIUMS[item.type] * itemSurchargePercent(item), 0);
}

function quotePremium(items: Item[]): number {
  const premiumInPercent =
    policyBasePremium(items) * (PERCENT + FIRST_INSURANCE_SURCHARGE_PERCENT) + itemSurchargesInPercent(items);
  return Math.ceil(premiumInPercent / PERCENT) + PROCESSING_FEE;
}

export function runScenario(scenario: Scenario): ScenarioResults {
  return { results: scenario.steps.map((step) => ({ premium: quotePremium(step.items) })) };
}
